//! Real terrain for the play state — the noise stage, wired to the wire.
//!
//! This closes the seam [`crate::world_send`] names: the chunks a client
//! receives are now generated by `rustmc-worldgen` rather than invented here.
//!
//! # Why only the noise stage
//!
//! It is the part with a 100.000000% claim behind it — bit-exact against
//! vanilla over 1.77M blocks — and it is the part that needs no world beyond
//! the chunk being generated. Surfaces, carvers and features all read
//! neighbouring chunks, so serving them needs a chunk *pipeline* with
//! neighbour management, which today exists only inside the whole-world dump
//! tool. Sending noise-stage terrain is therefore an honest increment rather
//! than a partial one: what it sends is exactly right, and what it omits is
//! named.
//!
//! A player will see stone, deepslate, water and the ore veins, with no
//! grass, no trees and no caves carved. That is the noise stage, correctly.
//!
//! # Block ids are the seam that remains
//!
//! The network carries global palette indices, and this maps our block names
//! through the extracted `block_props.json` — the same table the chunk-packet
//! gate uses to decode vanilla's own packets. A name the table does not know
//! is an error rather than a silent air block: a chunk quietly full of the
//! wrong id is the kind of wrong that looks like a worldgen bug.

use std::collections::BTreeMap;
use std::io;

use rustmc_worldgen::chunk_gen::{FillInputs, FillSettings, NoiseFill};
use rustmc_worldgen::density::aquifer::AquiferNoises;
use rustmc_worldgen::density::ore_vein::OreVeinifier;
use rustmc_worldgen::density::router::{OverworldNoises, OverworldRouter};
use rustmc_worldgen::noise::NoiseSeeding;

use crate::chunk::{ContainerKind, LevelChunkWithLight, LightData, PalettedContainer, Section};
use crate::world_send::OVERWORLD_SECTIONS;

/// Name-to-network-id for every block state, from the extract.
///
/// `Clone` because a caller that generates more than one area needs the same
/// table for each — reloading it per area would read 28,000 states off disk
/// again for a map that cannot differ.
#[derive(Clone)]
pub struct StateIds(BTreeMap<String, i32>);

impl StateIds {
    /// No states at all — for tests about the arithmetic around a table
    /// rather than about the table.
    #[must_use]
    pub const fn empty() -> Self {
        Self(BTreeMap::new())
    }

    /// Load from `block_props.json`, where the array index **is** the global
    /// state id.
    ///
    /// # Errors
    /// If the file is missing or not the expected shape.
    pub fn load(path: &std::path::Path) -> io::Result<Self> {
        let text = std::fs::read_to_string(path)?;
        let doc: serde_json::Value = serde_json::from_str(&text).map_err(io::Error::other)?;
        // `table` is the state list; each entry carries its own `id`, which
        // is the global palette index. Read the field rather than using the
        // array position: they agree today, and relying on that would make a
        // future reordering silently place the wrong blocks.
        let arr = doc
            .get("table")
            .and_then(serde_json::Value::as_array)
            .ok_or_else(|| io::Error::other("block_props.json has no `table` array"))?;
        let mut map = BTreeMap::new();
        for entry in arr {
            let (Some(name), Some(id)) = (
                entry.get("state").and_then(serde_json::Value::as_str),
                entry.get("id").and_then(serde_json::Value::as_i64),
            ) else {
                continue;
            };
            map.insert(
                name.to_string(),
                i32::try_from(id).map_err(io::Error::other)?,
            );
        }
        if map.is_empty() {
            return Err(io::Error::other("no states found in block_props.json"));
        }
        Ok(Self(map))
    }

    /// The network id for a state.
    ///
    /// # Errors
    /// If the table does not know the name — never a silent fallback to air.
    pub fn get(&self, state: &str) -> io::Result<i32> {
        self.0
            .get(state)
            .copied()
            .ok_or_else(|| io::Error::other(format!("no network id for block state {state}")))
    }
}

/// Load the noise parameters the router needs.
///
/// # Errors
/// If the vector file is missing or malformed.
pub fn noise_parameters(path: &std::path::Path) -> io::Result<OverworldNoises> {
    let text = std::fs::read_to_string(path)?;
    let doc: serde_json::Value = serde_json::from_str(&text).map_err(io::Error::other)?;
    let mut set = OverworldNoises::new();
    let entries = doc["parameters"]
        .as_array()
        .ok_or_else(|| io::Error::other("no `parameters` array"))?;
    for e in entries {
        let name = e["name"]
            .as_str()
            .ok_or_else(|| io::Error::other("noise entry has no name"))?;
        let first_octave = i32::try_from(
            e["firstOctave"]
                .as_i64()
                .ok_or_else(|| io::Error::other("no firstOctave"))?,
        )
        .map_err(io::Error::other)?;
        let amplitudes: Vec<f64> = e["amplitudes"]
            .as_array()
            .ok_or_else(|| io::Error::other("no amplitudes"))?
            .iter()
            .map(|v| {
                v.as_str()
                    .and_then(|s| s.parse::<i64>().ok())
                    .map(|bits| f64::from_bits(bits as u64))
                    .ok_or_else(|| io::Error::other("amplitude is not a long-as-string"))
            })
            .collect::<io::Result<_>>()?;
        set = set.with(
            name,
            rustmc_worldgen::noise::NoiseParameters::new(first_octave, amplitudes),
        );
    }
    Ok(set)
}

/// Generates noise-stage chunks for one seed.
pub struct Terrain {
    router: OverworldRouter,
    seeding: NoiseSeeding,
    ids: StateIds,
    air: i32,
}

impl Terrain {
    /// # Errors
    /// If the block table lacks `minecraft:air`.
    pub fn new(seed: i64, noises: &OverworldNoises, ids: StateIds) -> io::Result<Self> {
        let air = ids.get("minecraft:air")?;
        Ok(Self {
            router: OverworldRouter::new(seed, noises, false),
            seeding: NoiseSeeding::new(seed),
            ids,
            air,
        })
    }

    /// Generate one chunk and encode it as a network chunk.
    ///
    /// # Errors
    /// If a generated block has no network id.
    pub fn chunk(&self, chunk_x: i32, chunk_z: i32) -> io::Result<LevelChunkWithLight> {
        let fill = NoiseFill::new(
            FillInputs {
                final_density: self.router.final_density.clone(),
                aquifer_noises: AquiferNoises {
                    barrier: self.router.barrier.clone(),
                    fluid_level_floodedness: self.router.fluid_level_floodedness.clone(),
                    fluid_level_spread: self.router.fluid_level_spread.clone(),
                    lava: self.router.lava.clone(),
                    erosion: self.router.erosion.clone(),
                    depth: self.router.depth.clone(),
                },
                preliminary_surface_level: self.router.preliminary_surface_level.clone(),
                aquifer_random: self
                    .seeding
                    .source_for("minecraft:aquifer")
                    .fork_positional(),
                ore_veinifier: Some(OreVeinifier::new(
                    self.router.vein_toggle.clone(),
                    self.router.vein_ridged.clone(),
                    self.router.vein_gap.clone(),
                    self.seeding.source_for("minecraft:ore").fork_positional(),
                )),
                // No beardifier HERE, and the reason is narrower than the
                // one this comment used to give. It said "the live server
                // generates no structures at all", which was false even when
                // it was written — `crate::world` serves the whole pipeline
                // and that pipeline lays six overworld structure sets out
                // before the fill (`tests/served_structures.rs`). What is
                // true is that *this* module is the noise stage alone, with
                // no structure starts of its own to beard against, so `None`
                // is the only honest value it can pass.
                beardifier: None,
            },
            FillSettings::overworld(),
            chunk_x,
            chunk_z,
        )
        .fill();

        let mut sections = Vec::with_capacity(OVERWORLD_SECTIONS);
        for s in 0..OVERWORLD_SECTIONS {
            let base = -64 + i32::try_from(s).map_err(io::Error::other)? * 16;
            let mut values = vec![self.air; 4096];
            let mut solid = 0i16;
            // Section order is y, then z, then x — the same order the palette
            // container indexes cells in.
            for y in 0..16 {
                for z in 0..16 {
                    for x in 0..16 {
                        // Chunk-LOCAL x/z and WORLD y — the two are not the
                        // same convention and the debug assert only fires in
                        // a debug build, so a release server indexes out of
                        // bounds instead of telling you.
                        let name = rustmc_worldgen::anvil_bridge::block_name(
                            fill.get(x, base + y, z),
                            "minecraft:stone",
                        );
                        if name == "minecraft:air" {
                            continue;
                        }
                        let idx = (y as usize * 16 + z as usize) * 16 + x as usize;
                        values[idx] = self.ids.get(name)?;
                        solid += 1;
                    }
                }
            }
            sections.push(Section {
                non_empty_blocks: solid,
                fluid_count: 0,
                states: PalettedContainer::from_values(ContainerKind::BlockStates, &values),
                biomes: PalettedContainer::from_values(ContainerKind::Biomes, &[0; 64]),
            });
        }

        Ok(LevelChunkWithLight {
            chunk_x,
            chunk_z,
            heightmaps: Vec::new(),
            sections,
            // Empty because this generator HAS no block entities, not as a
            // stub. `beardifier: None` above says it plainly: the noise stage
            // places no structures, and nothing else here writes a chest, a
            // spawner or a pot. So an empty list is what vanilla would send
            // for the same chunk, and `World::chunk` — which does have a
            // store — builds a real one (PARITY-ROADMAP §32).
            //
            // THIS LINE BECOMES WRONG THE DAY THE PRECONDITION DOES. Give
            // this generator anything that places a block entity and the
            // payload silently omits it; no check covers this site, because
            // the chunk-send path reaches no recording (§70).
            block_entities: Vec::new(),
            light: LightData::default(),
        })
    }
}
